/**
 * Peer client version strings (e.g. from GET …/peer-info?client-details=true).
 * EL/CL/VC look like `Lighthouse/v8.1.3` or `Geth/v1.17.0-stable-…/linux-amd64/…`.
 * DV client versions may be bare (`v1.10.3` for Charon today) or `Family/…` later.
 *
 * Brand marks ship as React icon components under `components/icons/clients`.
 */

export type PeerClientSlot = "el" | "cl" | "dv" | "vc";

/** Structured client fields passed from the API consumer (no fetch here). */
export type PeerClientDetails = {
  beacon_client?: string | null;
  beacon_client_last_updated_at?: string | null;
  validator_client?: string | null;
  validator_client_last_updated_at?: string | null;
  execution_client?: string | null;
  execution_client_last_updated_at?: string | null;
  /** DV client version (API field name remains charon_version for now). */
  charon_version?: string | null;
  charon_version_last_updated_at?: string | null;
};

/**
 * Family token before the first `/`, or null if empty.
 * Bare DV versions (e.g. Charon `v1.10.3`) have no `/`.
 */
export const parseClientFamily = (
  raw: string | null | undefined,
): string | null => {
  if (!raw?.trim()) return null;
  return raw.split("/")[0]?.trim() || null;
};

/**
 * Logo family for the DV slot: prefer `Family/…` prefix; bare versions default
 * to Charon (current DV implementation) until other DVs report a family prefix.
 */
export const resolveDvClientFamily = (
  raw: string | null | undefined,
): string | null => {
  if (!raw?.trim()) return null;
  if (!raw.includes("/")) return "charon";
  const family = parseClientFamily(raw);
  if (!family || /^v?\d/i.test(family)) return "charon";
  return family.toLowerCase();
};

export const formatClientLastUpdated = (
  iso: string | null | undefined,
): string | null => {
  if (!iso) return null;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
};

export const CLIENT_SLOT_LABEL: Record<PeerClientSlot, string> = {
  el: "EL",
  cl: "CL",
  dv: "DV client",
  vc: "VC",
};
